# Builds the xptcall test as a native ARM exe for the phone and runs it there
# (real Windows on ARM ABI: MSVC C++ layout, clang-cl, phone CRT).
#   .\gecko\xptcall\test\run-phone.ps1          build + push + run
#   .\gecko\xptcall\test\run-phone.ps1 -NoRun   build only
# tests.inc is generated by gen.py (python3 gen.py tests.inc); a copy is committed.
param([switch]$NoRun)
$ErrorActionPreference = "Stop"
. "$PSScriptRoot\..\..\..\scripts\env.ps1"

$out = "$BuildRoot\tools\xptcall"
New-Item -ItemType Directory -Force $out | Out-Null
$srcs = @("$PSScriptRoot\..\xptcinvoke_arm_win.cpp", "$PSScriptRoot\..\xptcstubs_arm_win.cpp",
          "$PSScriptRoot\test_xptcall.cpp", "$PSScriptRoot\runtime.cpp")
$objs = @()
foreach ($s in $srcs) {
    $o = Join-Path $out ([IO.Path]::GetFileNameWithoutExtension($s) + ".obj")
    & "$Llvm\clang-cl.exe" @CFlags /std:c++14 /GR- -DXPTC_ARM_WIN_TEST "-I$PSScriptRoot" "-I$PSScriptRoot\.." /c $s "/Fo$o" 2>&1 | ForEach-Object { "$_" }
    if ($LASTEXITCODE -ne 0) { throw "Compile failed: $s" }
    $objs += $o
}
& "$Llvm\lld-link.exe" @LinkFlags @objs "/out:$out\xptcall-test.exe" 2>&1 | ForEach-Object { "$_" }
if ($LASTEXITCODE -ne 0) { throw "Link failed." }
Write-Host "Built $out\xptcall-test.exe" -ForegroundColor Cyan

if (-not $NoRun) {
    & "$Root\phone\phone-push.ps1" "$out\xptcall-test.exe"
    & "$Root\phone\phone-cmd.ps1" "C:\Data\Users\Public\Documents\retrofox\xptcall-test.exe"
}
